package behavioral.state.projects.vendingmachine;

import behavioral.state.projects.vendingmachine.model.Product;
import behavioral.state.projects.vendingmachine.vending.VendingMachine;

public class Main {

    public static void main(String[] args) {
        VendingMachine machine = new VendingMachine();

        machine.addProduct(new Product("Coke", 40, 5));
        machine.addProduct(new Product("Pepsi", 35, 2));

        machine.insertMoney(50);
        machine.selectProduct("Coke");
    }
}

package behavioral.state.projects.vendingmachine.model;

public class Product {
    private final String name;
    private final int price;
    private int quantity;

    public Product(String name, int price, int quantity) {
        this.name = name;
        this.price = price;
        this.quantity = quantity;
    }

    public String getName() {
        return this.name;
    }

    public int getPrice() {
        return this.price;
    }

    public int getQuantity() {
        return this.quantity;
    }

    public void reduceQuantity() {
        if (this.quantity <= 0) {
            throw new IllegalArgumentException("Not enough quantity available");
        }
        this.quantity -= 1;
    }

}

package behavioral.state.projects.vendingmachine.state;

import behavioral.state.projects.vendingmachine.model.Product;
import behavioral.state.projects.vendingmachine.vending.VendingMachine;

public class DispensingState implements IVendingMachineState {

    private final VendingMachine machine;

    public DispensingState(VendingMachine machine) {
        this.machine = machine;
    }

    @Override
    public void insertMoney(int amount) {
        System.out.println("Please wait. Dispensing in progress");
    }

    @Override
    public void selectProduct(String productName) {
        System.out.println("Already dispensing a product");
    }

    @Override
    public void dispenseProduct() {
        Product product = machine.getSelectedProduct();

        System.out.println("Dispensing: " + product.getName());
        product.reduceQuantity();

        int remaining = machine.getInsertedMoney() - product.getPrice();
        if (remaining > 0) {
            System.out.println("Returning change: ₹" + remaining);
        }

        machine.resetMoney();
        machine.setSelectedProduct(null);
        machine.setState(new IdleState(machine));
    }
}

package behavioral.state.projects.vendingmachine.state;

import behavioral.state.projects.vendingmachine.model.Product;
import behavioral.state.projects.vendingmachine.vending.VendingMachine;

public class HasMoneyState implements IVendingMachineState {

    private final VendingMachine machine;

    public HasMoneyState(VendingMachine machine) {
        this.machine = machine;
    }

    @Override
    public void insertMoney(int amount) {
        machine.addMoney(amount);
        System.out.println("Additional money inserted: ₹" + amount);
    }

    @Override
    public void selectProduct(String productName) {
        Product product = machine.getProduct(productName);

        if (product == null) {
            System.out.println("Invalid product selected");
            return;
        }

        if (product.getQuantity() <= 0) {
            System.out.println("Product out of stock");
            machine.setState(new OutOfStockState(machine));
            machine.dispenseProduct();
            return;
        }

        if (machine.getInsertedMoney() < product.getPrice()) {
            System.out.println("Insufficient balance");
            return;
        }

        machine.setSelectedProduct(product);
        machine.setState(new DispensingState(machine));
        machine.dispenseProduct();
    }

    @Override
    public void dispenseProduct() {
        System.out.println("Please select a product first");
    }
}

