package behavioral.state.projects.vendingmachine.state;

import behavioral.state.projects.vendingmachine.vending.VendingMachine;

public class OutOfStockState implements IVendingMachineState {

    private final VendingMachine machine;

    public OutOfStockState(VendingMachine machine) {
        this.machine = machine;
    }

    @Override
    public void insertMoney(int amount) {
        System.out.println("Product unavailable. Please wait.");
    }

    @Override
    public void selectProduct(String productName) {
        System.out.println("Selected product is out of stock");
    }

    @Override
    public void dispenseProduct() {
        System.out.println("Cannot dispense. Product out of stock.");
        int money = machine.getInsertedMoney();
        if (money > 0) {
            System.out.println("Refunding: ₹" + money);
            machine.resetMoney();
        }
        machine.setState(new IdleState(machine));
    }
}

package behavioral.state.projects.vendingmachine.vending;

import java.util.HashMap;
import java.util.Map;
import behavioral.state.projects.vendingmachine.model.Product;
import behavioral.state.projects.vendingmachine.state.IVendingMachineState;
import behavioral.state.projects.vendingmachine.state.IdleState;

public class VendingMachine {
    private IVendingMachineState currentState;
    private int insertedMoney;
    private final Map<String, Product> inventory;
    private Product selectedProduct;

    public VendingMachine() {
        this.currentState = new IdleState(this);
        this.insertedMoney = 0;
        this.inventory = new HashMap<>();
        this.selectedProduct = null;
    }

    // Public API — delegates to current state
    public void insertMoney(int amount) {
        currentState.insertMoney(amount);
    }

    public void selectProduct(String productName) {
        currentState.selectProduct(productName);
    }

    public void dispenseProduct() {
        currentState.dispenseProduct();
    }

    // State management
    public void setState(IVendingMachineState state) {
        this.currentState = state;
    }

    // Internal methods used by states
    public void addMoney(int amount) {
        this.insertedMoney += amount;
    }

    public int getInsertedMoney() {
        return this.insertedMoney;
    }

    public void resetMoney() {
        this.insertedMoney = 0;
    }

    public void setSelectedProduct(Product product) {
        this.selectedProduct = product;
    }

    public Product getSelectedProduct() {
        return this.selectedProduct;
    }

    public void addProduct(Product product) {
        inventory.put(product.getName(), product);
    }

    public Product getProduct(String productName) {
        return inventory.get(productName);
    }
}

